      const c = this.c
      if (c === undefined) this.err('unterminated string')
      this.i++
      if (c === q) return out
      if (c !== '\\' || q === "'") {
        out += c
        continue
      }
      const e = this.c
      if (e === undefined) this.err('unterminated string')
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.substr(this.i, 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) this.err('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else {
        const cp = String.fromCodePoint(this.s.codePointAt(this.i - 1))
        this.err(`invalid escape \\${cp}`)
      }
    }
