function assign(p, tbl, prefix, parts, v) {
  let t = tbl
  const path = [...prefix]
  for (let k = 0; k < parts.length - 1; k++) {
    const key = parts[k]
    path.push(key)
    let n = t.m.get(key)
    if (n === undefined) {
      n = newTable()
      t.m.set(key, n)
