  for (let k = 0; k < parts.length - 1; k++) {
    path.push(parts[k])
    let n = t.m.get(parts[k])
    if (n === undefined) {
      n = newTable()
      t.m.set(parts[k], n)
    } else if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
    else if (n.t !== 'table') p.err(`${path.join('.')} is not a table`)
    t = n
  }
  const last = parts[parts.length - 1]
  path.push(last)
  const n = t.m.get(last)
  const ps = path.join('.')
  if (aot) {
    const fresh = newTable()
    if (n === undefined) t.m.set(last, { t: 'array', items: [fresh], aot: true })
    else if (n.t === 'array' && n.aot) n.items.push(fresh)
    else p.err(`${ps} is not an array of tables`)
    return { cur: fresh, path }
  }
  if (n === undefined) {
    const nt = newTable()
    nt.hdr = true
    t.m.set(last, nt)
    return { cur: nt, path }
  }
  if (n.t !== 'table') p.err(`${ps} is not a table`)
  if (n.hdr) p.err(`table ${ps} is defined twice`)
  n.hdr = true
  return { cur: n, path }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((s, idx) => {
    const p = new LineParser(s, idx + 1)
    p.ws()
    if (p.c === undefined || p.c === '#' || p.c === ';') return
    if (p.c === '[') {
      const r = header(p, root)
      cur = r.cur
      curPath = r.path
      return
    }
    p.pair(cur, curPath, false)
    p.ws()
    if (!p.atEnd()) p.err('trailing text after a value')
  })
  return root
}
